const TRACKCO_API_URL = 'https://api.tracksale.co';
import axios from 'axios';

const API_KEY = '5626049ab7c8b6a927424dd0d7a033d4ac50e4f220a66162e905c75ac8b0';
const ORG_ID = '62e53fd5-4b10-41ba-741d-d46b58b89431';

// Create axios instance with default config
const api = axios.create({
  baseURL: TRACKCO_API_URL,
  headers: {
    'apikey': API_KEY,
    'Content-Type': 'application/json',
    'Accept': 'application/json'
  }
});

export const fetchNPSData = async () => {
  try {
    const response = await fetch('http://localhost:3001/api/nps-data');
    
    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const data = await response.json();
    console.log('API Response:', data);
    return data;
    
  } catch (error) {
    console.error('API Error:', error);
    throw new Error(`API Error: ${error.message}`);
  }
};